inst._zod.check = (payload) => {
  const input = payload.value;

  if (isInt) {
    if (!Number.isInteger(input)) {
      // invalid_format issue
      // payload.issues.push({
      //   expected: def.format,
      //   format: def.format,
      //   code: "invalid_format",
      //   input,
      //   inst,
      // });
      // invalid_type issue
      payload.issues.push({
        expected: origin,
        format: def.format,
        code: "invalid_type",
        continue: false,
        input,
        inst,
      });

      return;

      // not_multiple_of issue
      // payload.issues.push({
      //   code: "not_multiple_of",
      //   origin: "number",
      //   input,
      //   inst,
      //   divisor: 1,
      // });
    }
    if (!Number.isSafeInteger(input)) {
      if (input > 0) {
        // too_big
        payload.issues.push({
          input,
          code: "too_big",
          maximum: Number.MAX_SAFE_INTEGER,
          note: "Integers must be within the safe integer range.",
          inst,
          origin,
          inclusive: true,
          continue: !def.abort,
        });
      } else {
        // too_small
        payload.issues.push({
          input,
          code: "too_small",
          minimum: Number.MIN_SAFE_INTEGER,
          note: "Integers must be within the safe integer range.",
          inst,
          origin,
          inclusive: true,
          continue: !def.abort,
        });
      }

      return;
    }
  }

  if (input < minimum) {
    payload.issues.push({
      origin: "number",
      input,
      code: "too_small",
      minimum,
      inclusive: true,
      inst,
      continue: !def.abort,
    });
  }

  if (input > maximum) {
    payload.issues.push({
      origin: "number",
      input,
      code: "too_big",
      maximum,
      inclusive: true,
      inst,
      continue: !def.abort,
    } as any);
  }
